uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// --- ASSETS ---
uniform sampler2D iChannel0; 
uniform sampler2D iChannel1; 

// --- STANDARD CONTROLS ---
uniform float u_speed;
uniform float u_camera_dist; 
uniform float u_fov;
uniform float u_glow_intensity;

// --- VISUAL CONTROLS ---
uniform float u_turbulence_strength;
uniform float u_cloud_height; // Reused as tunnel radius
uniform float u_color_shift;
uniform float u_density_factor;
uniform float u_tunnel_twist; 
uniform float u_exit_light_size; 
uniform float u_exit_light_bright; 

// --- NEW ETHEREAL CONTROLS ---
uniform float u_ethereal_bloom;

out vec4 fragColor;

// --- LUMINA MATH LIB ---
#define PI 3.14159265359

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// --- MAIN RENDER LOOP ---
void main() {
    // 1. Setup UVs and Ray Direction
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // Create the ray direction for a forward-moving perspective
    vec3 rd = normalize(vec3(uv, 1.0 / u_fov)); 

    // Animation Time
    float t = iTime * u_speed;

    // Raymarching Variables
    vec4 col = vec4(0.0);
    float dist = u_camera_dist; 
    float stepSize = 0.0;

    // --- VOLUMETRIC MARCH ---
    for(int i = 0; i < 80; i++) {

        // Current Position along Ray
        vec3 p = dist * rd;
        p.z += t; // Forward motion

        // Apply twist to the tunnel based on depth
        p.xy *= rot(p.z * u_tunnel_twist + t * 0.1);

        // --- TURBULENCE LOOP (FBM-ish) ---
        float scale = 2.5;
        for(int j = 0; j < 4; j++) {
            p += u_turbulence_strength * sin(p.yzx * scale + t * 0.2) / scale;
            scale *= 1.6; 
            if (scale > 40.0) break;
        }

        // --- CYLINDRICAL DENSITY CALCULATION ---
        float radius = u_cloud_height * 2.0;
        float tunnelDist = length(p.xy) - radius;

        // Calculate Step Size
        float stepFactor = max(abs(tunnelDist), 0.02);
        stepSize = stepFactor * 0.45;

        // Advance Ray
        dist += stepSize;

        // --- COLOR ACCUMULATION: ETHEREAL ORANGES ---
        float angle = atan(p.y, p.x);

        // Modified hue logic for Oranges/Golds/Ambers
        // Shift base hue towards the 0.05-0.15 range (orange spectrum)
        float hueOffset = u_color_shift * 2.0;
        vec3 orangeBase = vec3(1.0, 0.4, 0.1); // Burnt Orange
        vec3 goldBase   = vec3(1.0, 0.8, 0.2); // Golden Glow

        // Dynamic mixing based on distance and rotation
        float mixVal = sin(p.z * 0.2 + angle) * 0.5 + 0.5;
        vec3 baseColor = mix(orangeBase, goldBase, mixVal);

        // Glow logic based on proximity to the tunnel wall
        float glow = exp(-abs(tunnelDist) * (8.0 / u_density_factor));

        // Accumulate intensity with an emphasis on soft falloff
        float attenuation = 1.0 / (1.0 + dist * 0.2);
        col.rgb += baseColor * glow * (u_glow_intensity * 0.06) * attenuation;

        // Optimization: early exit if color is saturated
        if(col.a > 0.99) break;
    }

    // --- THE LIGHT AT THE END OF THE TUNNEL (ETHEREAL SUN) ---
    // Make the exit light a soft golden bloom
    float distToCenter = length(uv);
    float exitGlow = pow(max(0.0, 1.0 - distToCenter / u_exit_light_size), 3.0);
    vec3 exitColor = vec3(1.0, 0.7, 0.3) * exitGlow * u_exit_light_bright;

    // --- POST PROCESSING ---
    vec3 finalCol = col.rgb + exitColor;

    // Add Ethereal Bloom / Haze
    finalCol += (vec3(1.0, 0.5, 0.1) * u_ethereal_bloom * 0.2) / (1.0 + distToCenter * 4.0);

    // Contrast and Tone Mapping for a cinematic feel
    finalCol = smoothstep(-0.05, 1.3, finalCol);
    finalCol = pow(finalCol, vec3(0.9)); // Slight gamma adjustment for "ethereal" softness

    // Vignette
    finalCol *= 1.1 - dot(uv, uv) * 0.7;

    fragColor = vec4(finalCol, 1.0);
}
